parameters.jsCode:
// Normalises TheSportsDB response into the exact contract Build project JSON
// reads, and falls back to a bundled demo matchday whenever the API cannot
// deliver one — the workflow renders something meaningful on a fresh import
// with zero external accounts.
//
// Live response shape (captured 2026-07-28 with the public test key:
// GET https://www.thesportsdb.com/api/v1/json/123/eventspastleague.php?id=4328):
// { "events": [ { "idEvent": "2267452",
//     "strEvent": "West Ham United vs Leeds United",
//     "strLeague": "English Premier League", "strSeason": "2025-2026",
//     "strHomeTeam": "West Ham United", "strAwayTeam": "Leeds United",
//     "intHomeScore": "3", "intAwayScore": "0", "intRound": "38",
//     "dateEvent": "2026-05-24", "strTime": "15:00:00", "strStatus": "FT", ... } ] }
// NOTE: the public test key returned exactly ONE event (the most recent
// finished fixture). A personal key returns the last 15, which fills a full
// five-match recap — the builder handles 1..5 matches either way.
const cfg = $('Config').first().json;
const res = $input.first().json || {};

const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
const maxMatches = Math.max(1, Math.min(5, Number(cfg.maxMatches) || 5));

// ---- bundled demo matchday: the real 2023-24 EPL final day ----------------
const DEMO = {
  league: 'English Premier League',
  season: '2023-2024',
  events: [
    { home: 'Manchester City', away: 'West Ham', homeScore: 3, awayScore: 1, dateEvent: '2024-05-19', round: '38' },
    { home: 'Arsenal', away: 'Everton', homeScore: 2, awayScore: 1, dateEvent: '2024-05-19', round: '38' },
    { home: 'Liverpool', away: 'Wolves', homeScore: 2, awayScore: 0, dateEvent: '2024-05-19', round: '38' },
    { home: 'Brighton', away: 'Manchester United', homeScore: 0, awayScore: 2, dateEvent: '2024-05-19', round: '38' },
    { home: 'Chelsea', away: 'Bournemouth', homeScore: 2, awayScore: 1, dateEvent: '2024-05-19', round: '38' },
  ],
};

// ---- parse the live response ----------------------------------------------
const body = res.body;
const events = body && Array.isArray(body.events) ? body.events : [];
const finished = events
  .filter((e) => e && e.intHomeScore != null && e.intAwayScore != null && clean(e.strHomeTeam) && clean(e.strAwayTeam))
  .map((e) => ({
    home: clean(e.strHomeTeam),
    away: clean(e.strAwayTeam),
    homeScore: Number(e.intHomeScore),
    awayScore: Number(e.intAwayScore),
    dateEvent: clean(e.dateEvent),
    time: clean(e.strTime),
    round: clean(e.intRound),
    league: clean(e.strLeague),
    season: clean(e.strSeason),
  }))
  .filter((e) => Number.isFinite(e.homeScore) && Number.isFinite(e.awayScore))
  .sort((a, b) => (b.dateEvent + 'T' + b.time).localeCompare(a.dateEvent + 'T' + a.time));

let usingDemoData = false;
let matches = finished.slice(0, maxMatches);
let league;
let season;
if (!clean(cfg.sportsDbKey) || !matches.length) {
  usingDemoData = true;
  matches = DEMO.events.slice(0, maxMatches);
  league = DEMO.league;
  season = DEMO.season;
} else {
  league = matches[0].league || 'League';
  season = matches[0].season || '';
}

// ---- labels ---------------------------------------------------------------
const roundNum = clean(matches[0].round);
const roundLabel = /^\d+$/.test(roundNum) ? 'Matchday ' + roundNum : 'Latest results';

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const parts = (iso) => String(iso || '').split('-').map(Number);
const fmt = (iso) => {
  const [y, m, d] = parts(iso);
  return y && m && d ? d + ' ' + MONTHS[m - 1] + ' ' + y : '';
};
const newest = matches[0].dateEvent;
const oldest = matches[matches.length - 1].dateEvent;
let dateLine = fmt(newest);
if (oldest && newest && oldest !== newest) {
  const [oy, om, od] = parts(oldest);
  const [ny, nm] = parts(newest);
  dateLine = oy === ny && om === nm ? od + '-' + fmt(newest) : fmt(oldest) + ' - ' + fmt(newest);
}

// ---- writer prompt --------------------------------------------------------
// Built here so the OpenRouter node body stays readable. The scores below are
// ground truth — the model writes copy about them, it never outputs scores
// that reach the screen.
const list = matches
  .map((m, i) => (i + 1) + '. ' + m.home + ' ' + m.homeScore + '-' + m.awayScore + ' ' + m.away + (m.dateEvent ? ' (' + m.dateEvent + ')' : ''))
  .join('\n');

const promptText = 'League: ' + league + '\nRound: ' + roundLabel + (dateLine ? ' (' + dateLine + ')' : '') + '\nFinal scores, most recent first (ground truth — never contradict them):\n' + list + '\n\nWrite the on-screen copy for a vertical results-recap video. Rules:\n1. Return STRICT JSON only, exactly the shape shown at the end. No markdown fences.\n2. "title": an energetic recap headline for the whole round, EIGHT words maximum, no team bias.\n3. "matchLines": exactly ' + matches.length + ' entries, in the SAME order as the list above. Each "line" is a punchy caption for that match, TEN words maximum, energetic but neutral broadcast tone.\n4. Only say what the scoreline supports (comfortable win, thriller, goalless stalemate, upset). NEVER invent player names, goalscorers, minutes, cards or incidents.\n5. "closing": a sign-off for the video, TWELVE words maximum, inviting fans back for the next round.\n6. Plain ASCII only: no emoji, no hashtags, no curly quotes, no long dashes.\n\n{ "title": "...", "matchLines": [{ "home": "team", "away": "team", "line": "..." }], "closing": "..." }';

return [{
  json: {
    league,
    season,
    roundLabel,
    dateLine,
    usingDemoData,
    matchCount: matches.length,
    matches: matches.map((m) => ({ home: m.home, away: m.away, homeScore: m.homeScore, awayScore: m.awayScore, dateEvent: m.dateEvent })),
    promptText,
  },
}];

