// Parses the writer's JSON and hardens it: ASCII-normalised, word-clamped, one
// line per match in match order. A missing or short line gets a deterministic
// scoreline fallback instead of failing the run — the scores on screen come
// from the API either way.
const prep = $('Prepare results').first().json;
const res = $input.first().json;

const content = res && res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
if (!content) {
  throw new Error('The model returned no content: ' + JSON.stringify(res).slice(0, 400));
}

let script;
try {
  script = JSON.parse(content);
} catch (e) {
  const m = /\{[\s\S]*\}/.exec(content);
  if (!m) throw new Error('The model did not return JSON:\n' + String(content).slice(0, 400));
  script = JSON.parse(m[0]);
}

// Models slip curly quotes and dashes in even when told not to.
const toAscii = (s) =>
  String(s == null ? '' : s)
    .replace(/[‘’ʼ]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-')
    .replace(/…/g, '...')
    .replace(/\s+/g, ' ')
    .trim();

const clampWords = (s, n) => toAscii(s).split(' ').filter(Boolean).slice(0, n).join(' ');

const fallbackLine = (m) => {
  const hs = Number(m.homeScore);
  const as = Number(m.awayScore);
  if (hs === as) return 'All square at ' + hs + '-' + as;
  const winner = hs > as ? m.home : m.away;
  return winner + ' take it ' + Math.max(hs, as) + '-' + Math.min(hs, as);
};

const rawLines = Array.isArray(script.matchLines) ? script.matchLines : [];
const lines = prep.matches.map((m, i) => {
  const cand = rawLines[i] && clampWords(rawLines[i].line, 10);
  return cand && cand.length >= 8 ? cand : fallbackLine(m);
});

const title = clampWords(script.title, 8) || prep.league + ' results';
const closing = clampWords(script.closing, 12) || 'That is full time for this round';

return [{ json: { title, closing, lines } }];

// === buildProject — identical to the frame-reviewed standalone builder ===
// Scores are GROUND TRUTH from TheSportsDB (via Prepare results). The LLM only
// writes copy: title, one caption line per match, closing. It can never change
// a score on screen.
function buildProject(config, prep, recap, probe) {
  const cfg = config || {};
  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const round2 = (n) => Math.round(n * 100) / 100;

  // ---- brand knobs --------------------------------------------------------
  const accent = clean(cfg.brandAccent) || '#C6FF3A';
  const bg = clean(cfg.brandBackground) || '#08110B';
  const font = clean(cfg.font) || 'Archivo';
  const brandName = clean(cfg.brandName) || 'FULL TIME';
  const handle = clean(cfg.handle) || '@yourclub';
  const ctaText = clean(cfg.ctaText) || 'Follow for every matchday';

  const hexToRgb = (hex) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(clean(hex));
    if (!m) return null;
    const n = parseInt(m[1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  const rgba = (hex, a) => {
    const c = hexToRgb(hex) || [198, 255, 58];
    return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
  };
  const lighten = (hex, amt) => {
    const c = hexToRgb(hex) || [8, 17, 11];
    const h = (v) => ('0' + Math.min(255, v + amt).toString(16)).slice(-2);
    return '#' + h(c[0]) + h(c[1]) + h(c[2]);
  };

  // ---- data ---------------------------------------------------------------
  const matches = (Array.isArray(prep.matches) ? prep.matches : []).slice(0, 5);
  if (!matches.length) throw new Error('Prepare results delivered no matches — even the demo fallback is empty.');
  for (const m of matches) {
    if (!clean(m.home) || !clean(m.away)) throw new Error('A match is missing a team name: ' + JSON.stringify(m));
    if (!Number.isFinite(Number(m.homeScore)) || !Number.isFinite(Number(m.awayScore))) {
      throw new Error('A match has a non-numeric score: ' + JSON.stringify(m));
    }
  }
  const lines = Array.isArray(recap.lines) ? recap.lines : [];
  const league = clean(prep.league) || 'League';
  const roundLabel = clean(prep.roundLabel) || 'Latest results';
  const dateLine = clean(prep.dateLine);
  const title = clean(recap.title) || league + ' results';
  const closing = clean(recap.closing) || 'That is full time for this round';

  // ---- timing -------------------------------------------------------------
  // Scene transitions overlap their two scenes, so every non-last scene is
  // padded by its transition duration and the on-screen time stays as designed.
  const sceneBase = Math.min(6, Math.max(2.5, Number(cfg.sceneSeconds) || 3.4));
  const tSec = Math.min(0.8, Math.max(0.2, Number(cfg.transitionSeconds) || 0.45));
  const titleBase = 3.2;
  const titleT = 0.5;
  const outroBase = 3.6;

  // ---- cover video --------------------------------------------------------
  // Pinned portrait clip of a packed floodlit stadium at night, probed at
  // authoring time: 1440x2560 (same 9:16 aspect, no crop), 13.8 s, 19.5 MB.
  // The title scene (3.7 s) never outruns it.
  const COVER = 'https://videos.pexels.com/video-files/34930800/14796393_1440_2560_30fps.mp4';
  const coverVideo = clean(cfg.coverVideoOverride) || COVER;
  const titleDur = round2(titleBase + titleT);
  const outroDur = outroBase;

  // ---- music guard --------------------------------------------------------
  // `probe` is the full HEAD response for cfg.musicUrl. Unreachable or
  // oversized music must never fail the render — it is simply dropped.
  const musicUrl = clean(cfg.musicUrl);
  const limit = Number(cfg.maxMusicBytes) > 0 ? Number(cfg.maxMusicBytes) : 5242880;
  const headers = (probe && probe.headers) || {};
  const musicBytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  const musicOk = !!musicUrl && Number(probe && probe.statusCode) === 200 && (!musicBytes || musicBytes <= limit);
  const musicSkipped = musicOk ? null : (!musicUrl ? 'musicUrl empty' : (Number(probe && probe.statusCode) !== 200 ? 'HEAD ' + (probe && probe.statusCode || 'failed') : musicBytes + ' bytes > ' + limit));

  // ---- adaptive type ------------------------------------------------------
  // Greedy word-wrap estimate. Archivo 900 uppercase runs ~0.68 em average,
  // mixed-case 900 ~0.50 em (calibrated on the rendered design sources).
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(4, Math.floor(boxPx / (fontPx * avgEm)));
    let n = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      n += 1;
      used = Math.min(w.length, perLine);
    }
    return n;
  };

  const gradTop = lighten(bg, 12);
  const gradMid = lighten(bg, 5);

  // ---- title scene --------------------------------------------------------
  const roundLine = (league + ' · ' + roundLabel + (dateLine ? ' · ' + dateLine : '')).toUpperCase();
  const tLen = title.length;
  const titleSize = tLen <= 26 ? 76 : tLen <= 42 ? 66 : 58;
  const shadeSvg = "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='srShade' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='" + bg + "' stop-opacity='0.75'/><stop offset='0.4' stop-color='" + bg + "' stop-opacity='0.45'/><stop offset='0.72' stop-color='" + bg + "' stop-opacity='0.88'/><stop offset='1' stop-color='" + bg + "' stop-opacity='0.98'/></linearGradient></defs><rect width='1080' height='1920' fill='url(#srShade)'/><path d='M-40 1150 L1120 1070 L1120 1086 L-40 1166 Z' fill='" + rgba(accent, 0.4) + "'/><path d='M-40 1210 L1120 1130 L1120 1174 L-40 1254 Z' fill='" + accent + "'/></svg>";

  const titleScene = {
    id: 'title',
    duration: titleDur,
    backgroundColor: bg,
    transition: 'slideup',
    transitionId: 'm1',
    transitionDuration: titleT,
    visuals: [
      { type: 'VIDEO', src: coverVideo, width: 1080, height: 1920, position: 'center-center', resize: 'cover', volume: 0, track: 0, enterBegin: 0, exitEnd: titleDur },
      { type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: titleDur, svg: shadeSvg },
      {
        type: 'TEXT', x: 540, y: 170, anchor: 'top-center', track: 2, enterBegin: 0.15, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: titleDur,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: "<div style='text-align:center; color:rgba(255,255,255,0.85); font-size:23px; font-weight:700; letter-spacing:7px; text-shadow:0 2px 14px rgba(0,0,0,0.7);'>" + esc(handle.toUpperCase()) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: 1330, width: 940, anchor: 'top-center', track: 3, enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'circleopen', exitEnd: titleDur,
        style: { fontFamily: font, color: accent },
        html: "<div style='text-align:center; color:" + accent + "; font-size:34px; font-weight:900; letter-spacing:12px;'>" + esc(brandName.toUpperCase()) + "</div><div style='margin-top:14px; text-align:center; color:rgba(255,255,255,0.8); font-size:27px; font-weight:700; letter-spacing:3px;'>" + esc(roundLine) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: 1480, width: 940, anchor: 'top-center', track: 4, enterBegin: 0.55, enterEnd: 1.0, enterAnimation: 'smoothup', exitEnd: titleDur,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: "<div style='text-align:center; color:#FFFFFF; font-size:" + titleSize + "px; line-height:1.05; font-weight:900; letter-spacing:-2px;'>" + esc(title) + '</div>',
      },
    ],
  };

  // ---- match scenes -------------------------------------------------------
  const cardSvg = "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='srBg' cx='0.5' cy='0.38' r='1'><stop offset='0' stop-color='" + gradTop + "'/><stop offset='0.55' stop-color='" + gradMid + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#srBg)'/><rect x='70' y='640' width='940' height='640' rx='36' fill='rgba(255,255,255,0.03)' stroke='" + rgba(accent, 0.4) + "' stroke-width='1.5'/><rect x='534' y='716' width='12' height='488' rx='6' fill='" + rgba(accent, 0.45) + "'/><rect x='70' y='640' width='940' height='12' rx='6' fill='" + accent + "'/></svg>";

  const nameSizesUsed = [];
  const matchScenes = matches.map((m, i) => {
    const isLastMatch = i === matches.length - 1;
    const dur = round2(sceneBase + tSec); // outro always follows, so every match scene is padded
    const home = clean(m.home).toUpperCase();
    const away = clean(m.away).toUpperCase();
    const hs = Number(m.homeScore);
    const as = Number(m.awayScore);
    const winner = hs > as ? 'home' : hs < as ? 'away' : 'draw';
    // Uppercase Archivo 900 runs ~0.78 em per character (measured on the
    // rendered frames), and CSS only wraps at spaces — so the size must also be
    // capped by the LONGEST WORD or a name like BOURNEMOUTH overflows its
    // 420 px column.
    const L = Math.max(home.length, away.length);
    const longestWord = Math.max(...(home + ' ' + away).split(' ').map((w) => w.length), 1);
    const tierSize = L <= 8 ? 56 : L <= 12 ? 50 : L <= 17 ? 44 : L <= 24 ? 38 : 32;
    const wordCap = Math.floor(420 / (longestWord * 0.8));
    const nameSize = Math.max(26, Math.min(tierSize, wordCap));
    nameSizesUsed.push(nameSize);
    const maxScore = Math.max(hs, as);
    const scoreSize = maxScore >= 100 ? 110 : maxScore >= 10 ? 150 : 170;
    const line = clean(lines[i] || '');
    const chipText = matches.length > 1 ? 'MATCH ' + (i + 1) + ' OF ' + matches.length : 'FULL TIME';

    const col = (name, score, side) => {
      const isWin = winner === side;
      const isDraw = winner === 'draw';
      const nameColor = isDraw || isWin ? '#FFFFFF' : '#98A29B';
      const scoreColor = isWin ? accent : 'rgba(255,255,255,0.92)';
      const bar = isWin ? "<div style='margin:20px auto 0; width:130px; height:8px; border-radius:4px; background:" + accent + ";'></div>" : '';
      return "<div style='height:130px; display:flex; align-items:flex-end; justify-content:center;'><div style='text-align:center; color:" + nameColor + '; font-size:' + nameSize + "px; line-height:1.12; font-weight:900; letter-spacing:0px;'>" + esc(name) + "</div></div><div style='margin-top:24px; text-align:center; color:" + scoreColor + '; font-size:' + scoreSize + "px; line-height:1; font-weight:900;'>" + (side === 'home' ? hs : as) + '</div>' + bar;
    };

    return {
      id: 'm' + (i + 1),
      duration: dur,
      backgroundColor: bg,
      transition: 'slideup',
      transitionId: isLastMatch ? 'outro' : 'm' + (i + 2),
      transitionDuration: tSec,
      visuals: [
        { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: dur, svg: cardSvg },
        {
          type: 'TEXT', x: 540, y: 470, anchor: 'center-center', track: 1, enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: dur,
          style: { fontFamily: font, color: accent },
          html: "<span style='display:inline-block; background:" + accent + '; color:' + bg + "; padding:12px 34px; border-radius:10px; font-size:28px; font-weight:900; letter-spacing:6px;'>" + esc(chipText) + '</span>',
        },
        {
          type: 'TEXT', x: 305, y: 768, width: 420, anchor: 'top-center', track: 2, enterBegin: 0.3, enterEnd: 0.7, enterAnimation: 'smoothright', exitEnd: dur,
          style: { fontFamily: font, color: '#FFFFFF' },
          html: col(home, hs, 'home'),
        },
        {
          type: 'TEXT', x: 775, y: 768, width: 420, anchor: 'top-center', track: 3, enterBegin: 0.45, enterEnd: 0.85, enterAnimation: 'smoothleft', exitEnd: dur,
          style: { fontFamily: font, color: '#FFFFFF' },
          html: col(away, as, 'away'),
        },
        {
          type: 'TEXT', x: 540, y: 1360, width: 860, anchor: 'top-center', track: 4, enterBegin: 0.75, enterEnd: 1.15, enterAnimation: 'smoothup', exitEnd: dur,
          style: { fontFamily: font, color: '#B9C6BD' },
          html: "<div style='text-align:center; color:#B9C6BD; font-size:34px; line-height:1.4; font-weight:600;'>" + esc(line) + '</div>',
        },
        {
          type: 'TEXT', x: 540, y: 1780, anchor: 'center-center', track: 5, enterBegin: 0, exitEnd: dur,
          style: { fontFamily: font, color: 'rgba(255,255,255,0.55)' },
          html: "<div style='color:rgba(255,255,255,0.55); font-size:24px; font-weight:800; letter-spacing:5px;'>" + esc((brandName + ' · ' + roundLabel).toUpperCase()) + '</div>',
        },
      ],
    };
  });

  // ---- outro scene --------------------------------------------------------
  const cLen = closing.length;
  const closingSize = cLen <= 28 ? 76 : cLen <= 55 ? 64 : 54;
  const closingLines = wrapLines(closing, closingSize, 900, 0.5);
  const ctaY = Math.max(1150, Math.min(1560, Math.round(880 + closingLines * closingSize * 1.12 + 100)));
  const handleY = ctaY + 145;
  const outroSvg = "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='srEnd' cx='0.5' cy='0.38' r='0.9'><stop offset='0' stop-color='" + lighten(bg, 16) + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#srEnd)'/><circle cx='540' cy='620' r='120' fill='none' stroke='" + rgba(accent, 0.55) + "' stroke-width='3'/><path d='M480 560 h120 v34 c0 40 -26 66 -60 70 c-34 -4 -60 -30 -60 -70 z' fill='" + accent + "'/><path d='M480 570 h-24 a30 30 0 0 0 28 42' stroke='" + accent + "' stroke-width='8' fill='none'/><path d='M600 570 h24 a30 30 0 0 1 -28 42' stroke='" + accent + "' stroke-width='8' fill='none'/><rect x='528' y='664' width='24' height='30' fill='" + accent + "'/><rect x='498' y='694' width='84' height='16' rx='8' fill='" + accent + "'/></svg>";

  const outroScene = {
    id: 'outro',
    duration: outroDur,
    backgroundColor: bg,
    visuals: [
      { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: outroDur, svg: outroSvg },
      {
        type: 'TEXT', x: 540, y: 170, anchor: 'top-center', track: 1, enterBegin: 0.1, enterEnd: 0.45, enterAnimation: 'fade', exitEnd: outroDur,
        style: { fontFamily: font, color: 'rgba(255,255,255,0.8)' },
        html: "<div style='text-align:center; color:rgba(255,255,255,0.8); font-size:26px; font-weight:900; letter-spacing:10px;'>" + esc(brandName.toUpperCase()) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: 880, width: 900, anchor: 'top-center', track: 2, enterBegin: 0.25, enterEnd: 0.7, enterAnimation: 'smoothup', exitEnd: outroDur,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: "<div style='text-align:center; color:#FFFFFF; font-size:" + closingSize + "px; line-height:1.1; font-weight:900; letter-spacing:-1px;'>" + esc(closing) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: ctaY, anchor: 'top-center', track: 3, enterBegin: 0.7, enterEnd: 1.15, enterAnimation: 'circleopen', exitEnd: outroDur,
        style: { fontFamily: font, color: accent },
        html: "<div style='display:inline-block; background:" + accent + '; color:' + bg + "; border-radius:999px; padding:24px 60px; font-size:34px; font-weight:900;'>" + esc(ctaText) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: handleY, anchor: 'top-center', track: 4, enterBegin: 1.0, enterEnd: 1.4, enterAnimation: 'fade', exitEnd: outroDur,
        style: { fontFamily: font, color: 'rgba(255,255,255,0.65)' },
        html: "<div style='text-align:center; color:rgba(255,255,255,0.65); font-size:27px; font-weight:600; letter-spacing:4px;'>" + esc(handle) + '</div>',
      },
    ],
  };

  const scenes = [titleScene].concat(matchScenes, [outroScene]);
  const sumDur = scenes.reduce((a, s) => a + s.duration, 0);
  const sumTrans = scenes.reduce((a, s) => a + (s.transitionDuration || 0), 0);
  const totalSeconds = round2(sumDur - sumTrans);

  // The render API only allows letters, digits, spaces, _ and - in `name`.
  const safeName = ('sports-recap-' + league + '-' + roundLabel).toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);

  const payload = {
    name: safeName || 'sports-recap',
    resolution: 'instagram-reel',
    frameRate: 30,
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes,
  };
  // NOTE: no `track` on audios — the render API rejects audios[].track.
  if (musicOk) payload.audios = [{ src: musicUrl, volume: Number(cfg.musicVolume) > 0 ? Number(cfg.musicVolume) : 0.16 }];

  return {
    payload,
    meta: {
      matchCount: matches.length,
      league,
      roundLabel,
      dateLine,
      title,
      closing,
      usingDemoData: !!prep.usingDemoData,
      musicIncluded: musicOk,
      musicSkipped,
      musicUrl,
      musicBytes,
      coverVideo,
      totalSeconds,
      titleSize,
      closingSize,
      nameSizes: nameSizesUsed,
      scores: matches.map((m) => m.homeScore + '-' + m.awayScore),
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const prep = $('Prepare results').first().json;
const recap = $('Parse recap').first().json;
const probe = $input.first().json || {};
const built = buildProject(config, prep, recap, probe);
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    title: d.meta.title,
    league: d.meta.league,
    round: d.meta.roundLabel,
    matches: d.meta.matchCount,
    usingDemoData: d.meta.usingDemoData,
    musicIncluded: d.meta.musicIncluded,
    editorLink,
    draftId,
    creditsRequired: d.creditsRequired,
    videoSeconds: d.meta.totalSeconds,
    warnings: d.warnings,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render for real.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run. `usingDemoData` tells you whether this recap
// came from TheSportsDB or from the bundled demo matchday (API down or
// sportsDbKey empty).
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    title: build.meta.title,
    league: build.meta.league,
    round: build.meta.roundLabel,
    matches: build.meta.matchCount,
    usingDemoData: build.meta.usingDemoData,
    musicIncluded: build.meta.musicIncluded,
    videoSeconds: build.meta.totalSeconds,
    creditsCharged: build.creditsRequired,
    handle: cfg.handle,
  },
}];
